import * as React from "react"
import { FocusIcon, MaximizeIcon, ZoomInIcon, ZoomOutIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

import { Connectors } from "./connectors"
import { DEFAULT_LAYOUT_OPTIONS } from "./layout"
import { MemoPersonCard, personLabel } from "./person-card"
import type { PersonCardContext } from "./person-card"
import type { LayoutOptions, Person, Rect, Relationship } from "./types"
import { useFamilyTree, useGraphDiagnostics } from "./use-family-tree"
import type { FocusMode } from "./use-family-tree"
import { useViewport } from "./use-viewport"

import "./family-tree.css"

export interface FamilyTreeProps extends React.ComponentProps<"div"> {
  people: Person[]
  /** Controlled focus. Pair with `onFocusChange`. */
  focusId?: string | null
  defaultFocusId?: string | null
  onFocusChange?: (personId: string | null) => void
  focusMode?: FocusMode
  defaultFocusMode?: FocusMode
  onFocusModeChange?: (mode: FocusMode) => void
  /** Override the rendered card entirely. */
  renderCard?: (context: PersonCardContext) => React.ReactNode
  /** Rewrite the calculated relationship term, for i18n or house style. */
  formatRelationship?: (relationship: Relationship, person: Person) => string
  layout?: Partial<LayoutOptions>
  showToolbar?: boolean
  showGenerationRules?: boolean
}

export function FamilyTree({
  people,
  focusId: focusIdProp,
  defaultFocusId = null,
  onFocusChange,
  focusMode: focusModeProp,
  defaultFocusMode = "highlight",
  onFocusModeChange,
  renderCard,
  formatRelationship,
  layout: layoutOptions,
  showToolbar = true,
  showGenerationRules = true,
  className,
  ...props
}: FamilyTreeProps) {
  const [focusIdState, setFocusIdState] = React.useState(defaultFocusId)
  const focusId = focusIdProp !== undefined ? focusIdProp : focusIdState

  const [focusModeState, setFocusModeState] = React.useState(defaultFocusMode)
  const focusMode = focusModeProp ?? focusModeState

  const opts = React.useMemo(
    () => ({ ...DEFAULT_LAYOUT_OPTIONS, ...layoutOptions }),
    [layoutOptions]
  )

  const model = useFamilyTree({ people, focusId, focusMode, layout: opts })
  useGraphDiagnostics(model.graph)

  const {
    containerRef,
    transform,
    isPanning,
    size,
    fitTo,
    centerOn,
    zoomBy,
    handlers,
  } = useViewport({ fitBottomInset: showToolbar ? 72 : 0 })

  /* ------------------------------ focus moves ------------------------------ */

  const setFocus = React.useCallback(
    (personId: string | null) => {
      if (focusIdProp === undefined) setFocusIdState(personId)
      onFocusChange?.(personId)
    },
    [focusIdProp, onFocusChange]
  )

  const setFocusMode = React.useCallback(
    (mode: FocusMode) => {
      if (focusModeProp === undefined) setFocusModeState(mode)
      onFocusModeChange?.(mode)
    },
    [focusModeProp, onFocusModeChange]
  )

  /** Bounding box of the focus person's line, for the camera to frame. */
  const lineageBounds = React.useMemo((): Rect | null => {
    if (!model.lineage) return null

    const nodes = model.layout.nodes.filter((node) =>
      model.lineage!.all.has(node.personId)
    )
    if (nodes.length === 0) return null

    const minX = Math.min(...nodes.map((n) => n.x))
    const minY = Math.min(...nodes.map((n) => n.y))
    const maxX = Math.max(...nodes.map((n) => n.x + n.width))
    const maxY = Math.max(...nodes.map((n) => n.y + n.height))

    return { x: minX, y: minY, width: maxX - minX, height: maxY - minY }
  }, [model.lineage, model.layout])

  const fitAll = React.useCallback(() => {
    fitTo(model.layout.bounds)
  }, [fitTo, model.layout.bounds])

  // Frame the whole tree once the container has a real size, and again whenever
  // the dataset changes shape. Without the size guard this fires against a
  // zero-width container on the first paint and the tree opens off-screen.
  const boundsKey = `${model.layout.bounds.width}x${model.layout.bounds.height}`
  const hasSize = size.width > 0 && size.height > 0
  // Keyed on the bounds *value*, not on `fitAll`, whose identity changes with
  // every layout recompute — depending on it would re-frame the tree on each
  // focus change and fight the lineage camera below.
  React.useEffect(() => {
    // oxlint-disable-next-line react/exhaustive-effect-dependencies
    if (hasSize) fitAll()
  }, [boundsKey, hasSize])

  // Follow the focus person, but only once the user has actually chosen
  // someone. Re-framing on the first paint would hide most of the family behind
  // whatever `defaultFocusId` happened to be.
  const settled = React.useRef(false)
  // Deliberately fires on focus changes only. `lineageBounds` changes whenever
  // the layout does, and following that would yank the camera during ordinary
  // re-renders rather than when the user picks someone.
  React.useEffect(() => {
    if (!hasSize) return
    if (!settled.current) {
      settled.current = true
      return
    }
    // oxlint-disable-next-line react/exhaustive-effect-dependencies
    if (lineageBounds) fitTo(lineageBounds)
  }, [focusId, focusMode, hasSize])

  const centerOnFocus = React.useCallback(() => {
    const node = focusId ? model.layout.nodeById.get(focusId) : null
    if (node)
      centerOn({ x: node.x + node.width / 2, y: node.y + node.height / 2 })
    else fitAll()
  }, [focusId, model.layout, centerOn, fitAll])

  /* ---------------------------- keyboard moves ---------------------------- */

  // Arrow keys move the selection; DOM focus has to follow it, or a screen
  // reader announces nothing when the selected card changes.
  const movedByKeyboard = React.useRef(false)

  const onKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (!focusId) return
      const target = navigate(event.key, focusId, model)
      if (!target) return
      event.preventDefault()
      movedByKeyboard.current = true
      setFocus(target)
    },
    [focusId, model, setFocus]
  )

  React.useEffect(() => {
    if (!movedByKeyboard.current || !focusId) return
    movedByKeyboard.current = false

    const card = containerRef.current?.querySelector<HTMLElement>(
      `[data-person-id="${CSS.escape(focusId)}"] [data-slot="family-tree-select"]`
    )
    // The camera is a transform, so let it do the moving — the browser's own
    // scroll-into-view would fight it.
    card?.focus({ preventScroll: true })
  }, [focusId, containerRef])

  /* -------------------------------- render -------------------------------- */

  const rowHeight = opts.cardHeight + opts.rowGap
  const lineageSet = model.lineage?.all ?? null

  return (
    <div
      data-slot="family-tree"
      data-focus-mode={focusMode}
      className={cn(
        "relative size-full overflow-hidden bg-background",
        className
      )}
      {...props}
    >
      {/* `application` is a widget role: it tells assistive technology to pass
          arrow keys through to the tree rather than using them to browse. */}
      {/* oxlint-disable-next-line jsx-a11y/no-noninteractive-element-interactions, jsx-a11y/no-noninteractive-tabindex */}
      <div
        ref={containerRef}
        data-slot="family-tree-viewport"
        role="application"
        aria-label="Family tree"
        aria-describedby="family-tree-help"
        // oxlint-disable-next-line jsx-a11y/no-noninteractive-tabindex
        tabIndex={0}
        onKeyDown={onKeyDown}
        className={cn(
          "size-full outline-none",
          isPanning ? "cursor-grabbing" : "cursor-grab"
        )}
        {...handlers}
      >
        <div
          data-slot="family-tree-surface"
          className="relative"
          style={{
            width: model.layout.bounds.width,
            height: model.layout.bounds.height,
            transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale})`,
          }}
        >
          {showGenerationRules
            ? model.layout.generations.map((row) => (
                <React.Fragment key={row.generation}>
                  <div
                    data-slot="family-tree-generation-rule"
                    style={{
                      top: row.y - opts.rowGap / 2,
                      width: model.layout.bounds.width,
                    }}
                  />
                  <span
                    className="absolute -translate-x-full pr-3 text-[11px] text-muted-foreground/70 tabular-nums"
                    style={{ top: row.y, left: 0 }}
                  >
                    {`Gen ${row.generation + 1}`}
                  </span>
                </React.Fragment>
              ))
            : null}

          <Connectors
            layout={model.layout}
            branchOf={model.branchOf}
            statusOf={(unionId) =>
              model.visibleGraph.unionById.get(unionId)?.status
            }
            lineage={lineageSet}
            rowGap={opts.rowGap}
            cardWidth={opts.cardWidth}
          />

          {model.layout.nodes.map((node) => {
            const person = model.visibleGraph.personById.get(node.personId)
            if (!person) return null

            const relationship = model.relationshipOf(node.personId)
            const context: PersonCardContext = {
              person,
              generation: node.generation,
              branch: model.branchOf.get(node.personId) ?? null,
              relationship:
                relationship && formatRelationship
                  ? {
                      ...relationship,
                      label: formatRelationship(relationship, person),
                    }
                  : relationship,
              isFocused: node.personId === focusId,
              isDimmed: lineageSet !== null && !lineageSet.has(node.personId),
            }

            // Selecting is a real <button> stretched over the card, rather than
            // the card itself being one: the card carries a link to the
            // person's location, and an <a> inside a <button> is invalid. The
            // overlay sits below that link so both stay clickable — and custom
            // cards passed to `renderCard` get the behaviour for free.
            return (
              <div
                key={node.personId}
                data-slot="family-tree-node"
                data-person-id={node.personId}
                data-dimmed={context.isDimmed || undefined}
                data-branch={context.branch ?? "none"}
                className="group/node"
                style={{
                  translate: `${node.x}px ${node.y}px`,
                  width: node.width,
                  height: node.height,
                }}
              >
                {renderCard ? (
                  renderCard(context)
                ) : (
                  <MemoPersonCard {...context} />
                )}
                <button
                  type="button"
                  data-slot="family-tree-select"
                  data-ft-interactive=""
                  aria-pressed={context.isFocused}
                  aria-label={personLabel(person, context.relationship)}
                  onClick={() => setFocus(node.personId)}
                  className="absolute inset-0 z-0 cursor-pointer rounded-lg outline-none focus-visible:ring-[2px] focus-visible:ring-ring/60"
                />
              </div>
            )
          })}
        </div>
      </div>

      <p id="family-tree-help" className="sr-only">
        {model.layout.nodes.length} people across{" "}
        {model.layout.generations.length} generations. Select a person to see
        how everyone is related to them, then use the arrow keys to move between
        parents, children and siblings.
      </p>

      {showToolbar ? (
        <Toolbar
          focusMode={focusMode}
          onFocusModeChange={setFocusMode}
          onZoomIn={() => zoomBy(1.25)}
          onZoomOut={() => zoomBy(0.8)}
          onFit={fitAll}
          onCenterFocus={centerOnFocus}
          hasFocus={Boolean(focusId)}
        />
      ) : null}

      {/* Keeps the row-height token in sync for consumers styling from CSS. */}
      <style>{`[data-slot="family-tree"]{--ft-row-height:${rowHeight}px}`}</style>
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*                                  Toolbar                                   */
/* -------------------------------------------------------------------------- */

function Toolbar({
  focusMode,
  onFocusModeChange,
  onZoomIn,
  onZoomOut,
  onFit,
  onCenterFocus,
  hasFocus,
}: {
  focusMode: FocusMode
  onFocusModeChange: (mode: FocusMode) => void
  onZoomIn: () => void
  onZoomOut: () => void
  onFit: () => void
  onCenterFocus: () => void
  hasFocus: boolean
}) {
  return (
    <div
      data-slot="family-tree-toolbar"
      data-ft-interactive=""
      className="absolute bottom-4 left-1/2 flex -translate-x-1/2 items-center gap-1 rounded-lg border bg-card/85 p-1 shadow-sm backdrop-blur"
    >
      <IconButton label="Zoom out" onClick={onZoomOut}>
        <ZoomOutIcon />
      </IconButton>
      <IconButton label="Zoom in" onClick={onZoomIn}>
        <ZoomInIcon />
      </IconButton>
      <IconButton label="Fit to screen" onClick={onFit}>
        <MaximizeIcon />
      </IconButton>
      <IconButton
        label="Centre on selection"
        onClick={onCenterFocus}
        disabled={!hasFocus}
      >
        <FocusIcon />
      </IconButton>

      <Separator orientation="vertical" className="mx-1 h-5" />

      {/* Base UI's ToggleGroup always deals in arrays, single-select or not. */}
      <ToggleGroup
        size="sm"
        value={[focusMode]}
        onValueChange={(value) => {
          const next = value[0] as FocusMode | undefined
          if (next) onFocusModeChange(next)
        }}
      >
        <ToggleGroupItem value="highlight" className="px-2 text-xs">
          Highlight
        </ToggleGroupItem>
        <ToggleGroupItem value="isolate" className="px-2 text-xs">
          Isolate
        </ToggleGroupItem>
      </ToggleGroup>
    </div>
  )
}

function IconButton({
  label,
  children,
  ...props
}: React.ComponentProps<typeof Button> & { label: string }) {
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button variant="ghost" size="icon" aria-label={label} {...props}>
            {children}
          </Button>
        }
      />
      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  )
}

/* -------------------------------------------------------------------------- */
/*                             Keyboard navigation                            */
/* -------------------------------------------------------------------------- */

/**
 * Moves selection by family relationship rather than document order: up and
 * down walk the generations, left and right step along the current row. That
 * matches what the tree looks like, which is the only mental model a keyboard
 * user has to go on.
 */
function navigate(
  key: string,
  focusId: string,
  model: ReturnType<typeof useFamilyTree>
): string | null {
  const { visibleGraph: graph, layout } = model
  const node = layout.nodeById.get(focusId)
  if (!node) return null

  if (key === "ArrowUp") {
    return (graph.parentsOf.get(focusId) ?? [])[0] ?? null
  }

  if (key === "ArrowDown") {
    return (graph.childrenOf.get(focusId) ?? [])[0] ?? null
  }

  if (key === "ArrowLeft" || key === "ArrowRight") {
    const row = layout.generations.find((r) => r.generation === node.generation)
    if (!row) return null
    const index = row.personIds.indexOf(focusId)
    const next = key === "ArrowLeft" ? index - 1 : index + 1
    return row.personIds[next] ?? null
  }

  return null
}

/**
 * Family tree tokens.
 *
 * Branch hues are OKLCH with a shared lightness and chroma, so the eight lines
 * read as one family of colours rather than eight unrelated ones, and stay
 * legible against both themes. Only lightness and chroma move between light and
 * dark — the hues themselves stay put, so a branch keeps its identity when the
 * theme flips.
 */

[data-slot="family-tree"] {
  --ft-card-width: 200px;
  --ft-card-height: 78px;
  --ft-partner-gap: 28px;
  --ft-sibling-gap: 32px;
  --ft-component-gap: 96px;
  --ft-row-gap: 72px;

  --ft-connector-width: 1.5px;
  --ft-connector-radius: 10px;
  --ft-dim-opacity: 0.28;

  --ft-branch-1: oklch(0.55 0.16 255);
  --ft-branch-2: oklch(0.58 0.15 155);
  --ft-branch-3: oklch(0.6 0.16 45);
  --ft-branch-4: oklch(0.55 0.16 330);
  --ft-branch-5: oklch(0.56 0.14 200);
  --ft-branch-6: oklch(0.58 0.15 95);
  --ft-branch-7: oklch(0.54 0.16 295);
  --ft-branch-8: oklch(0.57 0.15 20);
  --ft-branch-none: var(--muted-foreground);
}

.dark [data-slot="family-tree"] {
  --ft-branch-1: oklch(0.72 0.13 255);
  --ft-branch-2: oklch(0.75 0.12 155);
  --ft-branch-3: oklch(0.76 0.13 45);
  --ft-branch-4: oklch(0.72 0.13 330);
  --ft-branch-5: oklch(0.74 0.11 200);
  --ft-branch-6: oklch(0.78 0.12 95);
  --ft-branch-7: oklch(0.71 0.13 295);
  --ft-branch-8: oklch(0.73 0.13 20);
}

/* Resolved per card and per connector from the branch slot. */
[data-branch="0"] {
  --ft-branch: var(--ft-branch-1);
}
[data-branch="1"] {
  --ft-branch: var(--ft-branch-2);
}
[data-branch="2"] {
  --ft-branch: var(--ft-branch-3);
}
[data-branch="3"] {
  --ft-branch: var(--ft-branch-4);
}
[data-branch="4"] {
  --ft-branch: var(--ft-branch-5);
}
[data-branch="5"] {
  --ft-branch: var(--ft-branch-6);
}
[data-branch="6"] {
  --ft-branch: var(--ft-branch-7);
}
[data-branch="7"] {
  --ft-branch: var(--ft-branch-8);
}
[data-branch="none"] {
  --ft-branch: var(--ft-branch-none);
}

/* The pannable surface. Cards and connectors share one transform so they
   never drift apart at fractional zoom levels. */
[data-slot="family-tree-viewport"] {
  touch-action: none;
  overscroll-behavior: contain;
}

[data-slot="family-tree-surface"] {
  transform-origin: 0 0;
  will-change: transform;
}

[data-slot="family-tree-node"] {
  position: absolute;
  /* Contains the stretched select button and keeps the location link, which
     raises itself above it, from escaping into the page's stacking order. */
  isolation: isolate;
  width: var(--ft-card-width);
  height: var(--ft-card-height);
  transition:
    translate 320ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 200ms ease;
}

/* Off-lineage cards recede rather than disappear, so the shape of the whole
   family stays readable while one line is highlighted. */
[data-slot="family-tree-node"][data-dimmed="true"] {
  opacity: var(--ft-dim-opacity);
}

[data-slot="family-tree-connectors"] {
  position: absolute;
  inset: 0;
  overflow: visible;
  pointer-events: none;
}

[data-slot="family-tree-edge"] {
  fill: none;
  stroke: var(--ft-branch, var(--ft-branch-none));
  stroke-width: var(--ft-connector-width);
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: opacity 200ms ease;
}

[data-slot="family-tree-edge"][data-dimmed="true"] {
  opacity: var(--ft-dim-opacity);
}

/* An unmarried partnership reads as a dashed link; a dissolved one is
   dashed and struck through by the hatch marker. */
[data-slot="family-tree-edge"][data-status="partnership"],
[data-slot="family-tree-edge"][data-status="engaged"],
[data-slot="family-tree-edge"][data-status="separated"],
[data-slot="family-tree-edge"][data-status="divorced"] {
  stroke-dasharray: 5 4;
}

[data-slot="family-tree-generation-rule"] {
  position: absolute;
  left: 0;
  height: 0;
  border-top: 1px dashed var(--border);
  pointer-events: none;
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="family-tree-node"],
  [data-slot="family-tree-surface"],
  [data-slot="family-tree-edge"] {
    transition-duration: 0.01ms !important;
  }
}

import * as React from "react"
import {
  CircleHelpIcon,
  MapPinIcon,
  MarsIcon,
  NonBinaryIcon,
  VenusIcon,
} from "lucide-react"

import { Badge } from "@/components/ui/badge"
import { Card } from "@/components/ui/card"
import { cn } from "@/lib/utils"

import type { Person, Relationship, Sex } from "./types"

export interface PersonCardContext {
  person: Person
  generation: number
  /** Palette slot, or null when the person sits outside every coloured line. */
  branch: number | null
  relationship: Relationship | null
  isFocused: boolean
  isDimmed: boolean
}

export interface PersonCardProps extends Omit<PersonCardContext, "isDimmed"> {
  /** Drops the location row, for dense trees. */
  compact?: boolean
}

const SEX_ICON: Record<Sex, React.ComponentType<{ className?: string }>> = {
  male: MarsIcon,
  female: VenusIcon,
  other: NonBinaryIcon,
  unknown: CircleHelpIcon,
}

const SEX_LABEL: Record<Sex, string> = {
  male: "Male",
  female: "Female",
  other: "Non-binary",
  unknown: "Sex not recorded",
}

/** What a screen reader announces for a card: name plus how they are related. */
export function personLabel(
  person: Person,
  relationship: Relationship | null
): string {
  const term =
    relationship && relationship.type !== "self" && relationship.label
      ? relationship.label
      : null
  return term ? `${person.name}, ${term}` : person.name
}

/** "1948 – 2001", "b. 1975", "d. 1990", or nothing at all. */
export function lifespan(person: Person): string | null {
  const born = person.birth?.date
  const died = person.death?.date
  if (born && died) return `${born} – ${died}`
  if (born) return `b. ${born}`
  if (died) return `d. ${died}`
  return person.death ? "deceased" : null
}

/** Where a place name points. A search, not a pin — the data is free text. */
export function mapsUrl(place: string): string {
  return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(place)}`
}

export function PersonCard({
  person,
  generation,
  branch,
  relationship,
  isFocused,
  compact = false,
}: PersonCardProps) {
  const dates = lifespan(person)
  const deceased = Boolean(person.death)
  const SexIcon = SEX_ICON[person.sex]

  // "you" on the focused card is noise — the ring already says that.
  const badge =
    relationship && relationship.type !== "self" && relationship.label
      ? relationship.label
      : null

  const place = person.location ?? person.birth?.place

  // Nickname rides with the dates rather than trailing the name, which keeps
  // the name row short enough to survive truncation at this card width.
  const meta = [person.nickname && `“${person.nickname}”`, dates]
    .filter(Boolean)
    .join(" · ")

  return (
    <Card
      data-slot="family-tree-card"
      data-person-id={person.id}
      data-sex={person.sex}
      data-generation={generation}
      data-branch={branch ?? "none"}
      data-focused={isFocused || undefined}
      data-deceased={deceased || undefined}
      className={cn(
        "relative flex size-full flex-col gap-0 overflow-hidden rounded-lg py-2 pr-2.5 pl-3 select-none",
        "transition-[box-shadow,border-color]",
        "group-hover/node:border-[var(--ft-branch)]",
        isFocused &&
          "border-[var(--ft-branch)] ring-[2px] ring-[var(--ft-branch)]/35",
        deceased && "border-dashed"
      )}
    >
      {/* Branch identity as a spine, so several branches side by side stay
          distinguishable without washing the whole card in colour. */}
      <span
        aria-hidden
        className="absolute inset-y-0 left-0 w-[3px] bg-[var(--ft-branch)]"
      />

      {/* Name, led by the sex icon. */}
      <div className="flex items-center gap-1.5">
        <SexIcon
          className="size-3.5 shrink-0 text-[var(--ft-branch)]"
          aria-label={SEX_LABEL[person.sex]}
        />
        <span
          className={cn(
            "truncate text-[13px] leading-tight font-medium",
            deceased && "text-muted-foreground"
          )}
          title={person.name}
        >
          {person.name}
        </span>
      </div>

      {/* Nickname and lifespan. */}
      {meta ? (
        <div className="mt-0.5 truncate text-[10px] text-muted-foreground tabular-nums">
          {meta}
        </div>
      ) : null}

      {/* Relationship on the left, where it is; place on the right. */}
      <div className="mt-auto flex h-4 items-center justify-between gap-2">
        {badge ? (
          <Badge
            variant="secondary"
            className="h-4 shrink truncate px-1.5 text-[10px] font-normal"
          >
            {badge}
          </Badge>
        ) : (
          <span />
        )}

        {place && !compact ? (
          // Sits above the stretched select button that covers the card, so
          // the link stays reachable on its own.
          <a
            href={mapsUrl(place)}
            target="_blank"
            rel="noreferrer"
            data-ft-interactive=""
            className={cn(
              "group/place relative z-10 text-muted-foreground hover:text-foreground",
              "flex min-w-0 shrink items-center gap-0.5 text-[10px]"
            )}
            title={`Find ${place} on Google Maps`}
          >
            <MapPinIcon className="size-2.5 shrink-0" aria-hidden />
            <span className="truncate underline-offset-2 group-hover/place:underline">
              {place}
            </span>
          </a>
        ) : null}
      </div>
    </Card>
  )
}

export const MemoPersonCard = React.memo(PersonCard)

import * as React from "react"
import type { TreeLayout, UnionAnchor } from "./types"

export interface ConnectorsProps {
  layout: TreeLayout
  branchOf: Map<string, number>
  statusOf: (unionId: string) => string | undefined
  /** People currently on the focus person's line; null means "no focus". */
  lineage: Set<string> | null
  /** Vertical distance between one row's bottom and the next row's top. */
  rowGap: number
  /** Needed to inset the couple link so it starts at the cards' edges. */
  cardWidth: number
}

const RADIUS = 10

/**
 * Draws every relationship line as one SVG layer beneath the cards.
 *
 * The layer is a sibling of the card layer inside the same transformed
 * container — not a `<foreignObject>` wrapping the cards. WebKit ignores `x`
 * and `y` on `foreignObject`, which is why bracket libraries that nest their
 * HTML inside SVG collapse to the origin in Safari. Keeping the two as
 * independent layers over a shared transform sidesteps that entirely and still
 * guarantees the lines and the cards move together.
 */
export function Connectors({
  layout,
  branchOf,
  statusOf,
  lineage,
  rowGap,
  cardWidth,
}: ConnectorsProps) {
  return (
    <svg
      data-slot="family-tree-connectors"
      width={layout.bounds.width}
      height={layout.bounds.height}
      aria-hidden
    >
      {layout.unions.map((anchor) => (
        <UnionEdges
          key={anchor.unionId}
          anchor={anchor}
          branchOf={branchOf}
          status={statusOf(anchor.unionId)}
          lineage={lineage}
          rowGap={rowGap}
          cardWidth={cardWidth}
        />
      ))}
    </svg>
  )
}

function UnionEdges({
  anchor,
  branchOf,
  status,
  lineage,
  rowGap,
  cardWidth,
}: {
  anchor: UnionAnchor
  branchOf: Map<string, number>
  status?: string
  lineage: Set<string> | null
  rowGap: number
  cardWidth: number
}) {
  const { partnerPoints, childPoints } = anchor

  // The whole union takes one colour, from whichever partner has a branch.
  const branch =
    partnerPoints
      .map((p) => branchOf.get(p.personId))
      .find((b) => b !== undefined) ??
    childPoints
      .map((p) => branchOf.get(p.personId))
      .find((b) => b !== undefined)

  const onLine =
    lineage === null ||
    partnerPoints.some((p) => lineage.has(p.personId)) ||
    childPoints.some((p) => lineage.has(p.personId))

  const shared = {
    "data-slot": "family-tree-edge",
    "data-branch": branch ?? "none",
    "data-dimmed": onLine ? undefined : true,
  } as const

  const elements: React.ReactNode[] = []

  /* ----------------------------- couple link ----------------------------- */

  if (partnerPoints.length === 2) {
    const [left, right] =
      partnerPoints[0].x <= partnerPoints[1].x
        ? partnerPoints
        : [partnerPoints[1], partnerPoints[0]]

    // Start and end at the cards' facing edges — a centre-to-centre line would
    // spend most of its length hidden behind the two cards.
    const startX = left.x + cardWidth / 2
    const endX = right.x - cardWidth / 2

    elements.push(
      <line
        key="couple"
        {...shared}
        data-status={status}
        x1={startX}
        y1={left.y}
        x2={endX}
        y2={right.y}
      />
    )

    // A dissolved marriage gets a hatch through the middle of the link, the
    // convention genealogy charts use for a divorce.
    if (status === "divorced") {
      const midX = (startX + endX) / 2
      const midY = (left.y + right.y) / 2
      for (const offset of [-3, 3]) {
        elements.push(
          <line
            key={`hatch${offset}`}
            {...shared}
            data-status={undefined}
            x1={midX + offset - 3}
            y1={midY + 6}
            x2={midX + offset + 3}
            y2={midY - 6}
          />
        )
      }
    }
  }

  /* ---------------------------- descent lines ---------------------------- */

  if (childPoints.length > 0) {
    // The bus runs across the middle of the gap between the two rows, so the
    // drop and the stubs are the same length regardless of how tall cards are.
    const busY = anchor.y + rowGap / 2
    const childTop = Math.min(...childPoints.map((p) => p.y))

    elements.push(
      <path
        key="drop"
        {...shared}
        d={`M ${anchor.x} ${anchor.y} L ${anchor.x} ${busY}`}
      />
    )

    for (const child of childPoints) {
      elements.push(
        <path
          key={`child-${child.personId}`}
          {...shared}
          data-branch={branchOf.get(child.personId) ?? branch ?? "none"}
          data-dimmed={
            lineage === null || lineage.has(child.personId) ? undefined : true
          }
          d={elbow(anchor.x, busY, child.x, childTop)}
        />
      )
    }
  }

  return <>{elements}</>
}

/**
 * An orthogonal path from the sibling bus down into a child's top edge:
 * along the bus, a rounded corner, then straight down. A child sitting directly
 * below its parents gets a plain vertical line with no corner at all.
 */
function elbow(fromX: number, busY: number, toX: number, toY: number): string {
  const dx = toX - fromX
  if (Math.abs(dx) < 0.5) return `M ${fromX} ${busY} L ${toX} ${toY}`

  const direction = Math.sign(dx)
  const radius = Math.min(RADIUS, Math.abs(dx) / 2, Math.abs(toY - busY) / 2)
  const cornerX = toX - direction * radius

  return [
    `M ${fromX} ${busY}`,
    `L ${cornerX} ${busY}`,
    `Q ${toX} ${busY} ${toX} ${busY + radius}`,
    `L ${toX} ${toY}`,
  ].join(" ")
}

/**
 * Public data model.
 *
 * Only `id`, `name` and `sex` are required. Relationships are expressed flatly —
 * a person points at their parents and their partners — and the internal graph
 * derives "unions" (couples) from that. See `graph.ts` for the derivation.
 */

export type Sex = "male" | "female" | "other" | "unknown"

export type PartnershipStatus =
  | "married"
  | "partnership"
  | "engaged"
  | "divorced"
  | "separated"
  | "widowed"

export interface LifeEvent {
  /** Any string. ISO dates sort correctly; "1952" and "c. 1880" render as-is. */
  date?: string
  place?: string
}

export interface Partnership {
  partnerId: string
  status?: PartnershipStatus
  since?: string
  until?: string
}

export interface Person {
  id: string
  name: string
  sex: Sex

  /** Zero, one or two parents. More than two is reported as a diagnostic and truncated. */
  parentIds?: string[]
  /** Symmetric; a one-sided declaration is repaired during normalisation. */
  partnerIds?: string[]
  /** Richer form of `partnerIds`. Takes precedence for any pair it covers. */
  partnerships?: Partnership[]

  nickname?: string
  birth?: LifeEvent
  death?: LifeEvent
  location?: string
  /** Overrides the computed branch colour. */
  branchId?: string
  /** Anything else you want to reach in `renderCard`. */
  meta?: Record<string, unknown>
}

/**
 * A couple, derived rather than authored. Every descent connector hangs off one,
 * and distinct unions are what separate half-siblings from full siblings.
 */
export interface Union {
  id: string
  /** One partner (single parent) or two. Ordered for stable left-to-right placement. */
  partnerIds: string[]
  childIds: string[]
  status?: PartnershipStatus
  since?: string
  until?: string
}

export type DiagnosticCode =
  | "unknown-parent"
  | "unknown-partner"
  | "too-many-parents"
  | "self-reference"
  | "duplicate-id"
  | "parent-cycle"

export interface Diagnostic {
  code: DiagnosticCode
  personId: string
  message: string
}

export interface FamilyGraph {
  people: Person[]
  personById: Map<string, Person>
  unions: Union[]
  unionById: Map<string, Union>
  /** Unions a person is a partner in, in placement order. */
  unionsByPartner: Map<string, Union[]>
  /** The union a person is a child of, if any. */
  unionByChild: Map<string, Union>
  parentsOf: Map<string, string[]>
  childrenOf: Map<string, string[]>
  partnersOf: Map<string, string[]>
  diagnostics: Diagnostic[]
}

/* -------------------------------------------------------------------------- */
/*                                   Layout                                   */
/* -------------------------------------------------------------------------- */

export interface Rect {
  x: number
  y: number
  width: number
  height: number
}

export interface LayoutNode {
  personId: string
  generation: number
  /** Left edge, in abstract layout units. */
  x: number
  /** Top edge, in abstract layout units. */
  y: number
  width: number
  height: number
}

/** The point a union's descent connector drops from. */
export interface UnionAnchor {
  unionId: string
  generation: number
  x: number
  y: number
  /** Partner card mid-heights, for drawing the horizontal couple link. */
  partnerPoints: Array<{ personId: string; x: number; y: number }>
  childPoints: Array<{ personId: string; x: number; y: number }>
}

export interface GenerationRow {
  generation: number
  y: number
  height: number
  personIds: string[]
}

export interface TreeLayout {
  nodes: LayoutNode[]
  nodeById: Map<string, LayoutNode>
  unions: UnionAnchor[]
  generations: GenerationRow[]
  bounds: Rect
}

export interface LayoutOptions {
  cardWidth: number
  cardHeight: number
  /** Horizontal gap between two partners in the same union. */
  partnerGap: number
  /** Horizontal gap between adjacent sibling subtrees. */
  siblingGap: number
  /** Horizontal gap between disconnected components. */
  componentGap: number
  /** Vertical gap between generation rows. */
  rowGap: number
}

/* -------------------------------------------------------------------------- */
/*                                  Kinship                                   */
/* -------------------------------------------------------------------------- */

export type RelationshipKind = "self" | "blood" | "affinal" | "step" | "none"

export type RelationshipType =
  | "self"
  | "partner"
  | "ex-partner"
  | "parent"
  | "child"
  | "sibling"
  | "half-sibling"
  | "grandparent"
  | "grandchild"
  | "pibling" // aunt / uncle
  | "nibling" // niece / nephew
  | "cousin"
  | "unrelated"

export interface Relationship {
  type: RelationshipType
  kind: RelationshipKind
  /** Cousin degree: 1 = first cousin. Undefined for non-cousins. */
  degree?: number
  /** Generations removed, for cousins and niblings/piblings. */
  removed?: number
  /** Generations up or down the direct line: 1 = parent/child, 2 = grandparent. */
  steps?: number
  /** True when the link runs through a partner rather than by blood. */
  inLaw?: boolean
  /** The rendered term, e.g. "second cousin once removed". */
  label: string
}

/* -------------------------------------------------------------------------- */
/*                                  Branches                                  */
/* -------------------------------------------------------------------------- */

export interface BranchAssignment {
  /** personId -> palette slot (0-based), or undefined for the neutral branch. */
  branchOf: Map<string, number>
  /** Palette slot -> the ancestor line that seeded it. */
  seeds: Array<{ slot: number; personId: string; label: string }>
}

export interface Lineage {
  focusId: string
  ancestors: Set<string>
  descendants: Set<string>
  partners: Set<string>
  siblings: Set<string>
  /** Union of all of the above plus the focus person. */
  all: Set<string>
}

import type {
  Diagnostic,
  FamilyGraph,
  Partnership,
  PartnershipStatus,
  Person,
  Union,
} from "./types"

/** Stable key for a set of parents, order-independent. */
function unionKey(ids: string[]): string {
  return [...ids].sort().join("+")
}

function push<TKey, TValue>(
  map: Map<TKey, TValue[]>,
  key: TKey,
  value: TValue
) {
  const existing = map.get(key)
  if (existing) existing.push(value)
  else map.set(key, [value])
}

/**
 * Comparable sort key for a free-form date string. Pulls out the first 4-digit
 * year so "1952-03-01", "1952" and "c. 1952" all sort together, and returns
 * Infinity for anything undated so it lands last.
 */
export function dateKey(value: string | undefined): number {
  if (!value) return Number.POSITIVE_INFINITY
  const year = /\d{4}/.exec(value)
  if (!year) return Number.POSITIVE_INFINITY
  const month = /\d{4}-(\d{2})/.exec(value)
  const day = /\d{4}-\d{2}-(\d{2})/.exec(value)
  return (
    Number(year[0]) * 10000 +
    (month ? Number(month[1]) : 0) * 100 +
    (day ? Number(day[1]) : 0)
  )
}

/**
 * Builds the internal graph from the flat person list.
 *
 * Unions are derived in three passes:
 *   1. every distinct parent-set that has children becomes a union,
 *   2. every declared partnership without children becomes a childless union,
 *   3. each person's unions are ordered so successive partners lay out left to right.
 *
 * Bad input produces diagnostics rather than exceptions — a tree that renders
 * with a warning is more useful than one that throws.
 */
export function buildGraph(input: Person[]): FamilyGraph {
  const diagnostics: Diagnostic[] = []
  const personById = new Map<string, Person>()

  for (const person of input) {
    if (personById.has(person.id)) {
      diagnostics.push({
        code: "duplicate-id",
        personId: person.id,
        message: `Duplicate id "${person.id}"; the later entry was ignored.`,
      })
      continue
    }
    personById.set(person.id, person)
  }

  const people = [...personById.values()]

  /* ---------------------------- normalise parents --------------------------- */

  const parentsOf = new Map<string, string[]>()

  for (const person of people) {
    const raw = person.parentIds ?? []
    const parents: string[] = []

    for (const parentId of raw) {
      if (parentId === person.id) {
        diagnostics.push({
          code: "self-reference",
          personId: person.id,
          message: `"${person.name}" is listed as their own parent.`,
        })
        continue
      }
      if (!personById.has(parentId)) {
        diagnostics.push({
          code: "unknown-parent",
          personId: person.id,
          message: `"${person.name}" references unknown parent "${parentId}".`,
        })
        continue
      }
      if (!parents.includes(parentId)) parents.push(parentId)
    }

    if (parents.length > 2) {
      diagnostics.push({
        code: "too-many-parents",
        personId: person.id,
        message: `"${person.name}" has ${parents.length} parents; only the first two are laid out.`,
      })
      parents.length = 2
    }

    parentsOf.set(person.id, parents)
  }

  breakParentCycles(people, parentsOf, personById, diagnostics)

  /* --------------------------- normalise partners --------------------------- */

  // Symmetric partner set, plus the richest partnership record for each pair.
  const partnerSet = new Map<string, Set<string>>()
  const partnershipByPair = new Map<string, Partnership & { ownerId: string }>()

  const linkPartners = (a: string, b: string) => {
    if (!partnerSet.has(a)) partnerSet.set(a, new Set())
    if (!partnerSet.has(b)) partnerSet.set(b, new Set())
    partnerSet.get(a)!.add(b)
    partnerSet.get(b)!.add(a)
  }

  for (const person of people) {
    const declared: Array<{ partnerId: string; record?: Partnership }> = [
      ...(person.partnerIds ?? []).map((partnerId) => ({ partnerId })),
      ...(person.partnerships ?? []).map((record) => ({
        partnerId: record.partnerId,
        record,
      })),
    ]

    for (const { partnerId, record } of declared) {
      if (partnerId === person.id) {
        diagnostics.push({
          code: "self-reference",
          personId: person.id,
          message: `"${person.name}" is listed as their own partner.`,
        })
        continue
      }
      if (!personById.has(partnerId)) {
        diagnostics.push({
          code: "unknown-partner",
          personId: person.id,
          message: `"${person.name}" references unknown partner "${partnerId}".`,
        })
        continue
      }

      linkPartners(person.id, partnerId)

      // A `partnerships` record beats a bare `partnerIds` entry for the same pair.
      const key = unionKey([person.id, partnerId])
      if (record && !partnershipByPair.has(key)) {
        partnershipByPair.set(key, { ...record, ownerId: person.id })
      }
    }
  }

  /* ------------------------------ build unions ------------------------------ */

  const unionByKey = new Map<string, Union>()
  const orderedPeople = people // input order drives tie-breaks below

  const ensureUnion = (partnerIds: string[]): Union => {
    const key = unionKey(partnerIds)
    const existing = unionByKey.get(key)
    if (existing) return existing

    const record = partnershipByPair.get(key)
    const union: Union = {
      id: `u:${key}`,
      // Keep declaration order where we have it, so couples read consistently.
      partnerIds: orderPartners(partnerIds, orderedPeople),
      childIds: [],
      status: record?.status ?? inferStatus(partnerIds, personById),
      since: record?.since,
      until: record?.until,
    }
    unionByKey.set(key, union)
    return union
  }

  // Pass 1 — parent sets that have children.
  for (const person of orderedPeople) {
    const parents = parentsOf.get(person.id) ?? []
    if (parents.length === 0) continue
    ensureUnion(parents).childIds.push(person.id)
  }

  // Pass 2 — declared partnerships with no shared children.
  for (const [personId, partners] of partnerSet) {
    for (const partnerId of partners) {
      ensureUnion([personId, partnerId])
    }
  }

  /* ------------------------------- indexes -------------------------------- */

  const unions = [...unionByKey.values()]
  const unionById = new Map(unions.map((u) => [u.id, u]))
  const unionsByPartner = new Map<string, Union[]>()
  const unionByChild = new Map<string, Union>()
  const childrenOf = new Map<string, string[]>()
  const partnersOf = new Map<string, string[]>()

  for (const union of unions) {
    // Children read in birth order; undated children keep their input order.
    union.childIds.sort((a, b) => {
      const delta =
        dateKey(personById.get(a)?.birth?.date) -
        dateKey(personById.get(b)?.birth?.date)
      if (delta !== 0 && Number.isFinite(delta)) return delta
      return 0
    })

    for (const partnerId of union.partnerIds) {
      push(unionsByPartner, partnerId, union)
      for (const childId of union.childIds) push(childrenOf, partnerId, childId)
      for (const other of union.partnerIds) {
        if (other !== partnerId) push(partnersOf, partnerId, other)
      }
    }
    for (const childId of union.childIds) unionByChild.set(childId, union)
  }

  // Pass 3 — order each person's unions so successive partners lay out left to right.
  for (const [personId, list] of unionsByPartner) {
    list.sort((a, b) => unionOrder(a, personById) - unionOrder(b, personById))
    unionsByPartner.set(personId, list)
  }

  for (const person of people) {
    if (!parentsOf.has(person.id)) parentsOf.set(person.id, [])
    if (!childrenOf.has(person.id)) childrenOf.set(person.id, [])
    if (!partnersOf.has(person.id)) partnersOf.set(person.id, [])
  }

  return {
    people,
    personById,
    unions,
    unionById,
    unionsByPartner,
    unionByChild,
    parentsOf,
    childrenOf,
    partnersOf,
    diagnostics,
  }
}

/**
 * Sort key for one of a person's unions: the partnership start date if known,
 * else the earliest child's birth, else Infinity (undated unions trail).
 */
function unionOrder(union: Union, personById: Map<string, Person>): number {
  const since = dateKey(union.since)
  if (Number.isFinite(since)) return since

  let earliest = Number.POSITIVE_INFINITY
  for (const childId of union.childIds) {
    const born = dateKey(personById.get(childId)?.birth?.date)
    if (born < earliest) earliest = born
  }
  return earliest
}

/** Keeps partners in input order so a couple always renders the same way round. */
function orderPartners(ids: string[], people: Person[]): string[] {
  const index = new Map(people.map((p, i) => [p.id, i]))
  return [...ids].sort((a, b) => (index.get(a) ?? 0) - (index.get(b) ?? 0))
}

/**
 * With no explicit record, a couple where one partner has died reads as
 * "widowed" rather than "married". Everything else defaults to married.
 */
function inferStatus(
  partnerIds: string[],
  personById: Map<string, Person>
): PartnershipStatus {
  if (partnerIds.length < 2) return "partnership"
  const anyDeceased = partnerIds.some((id) => personById.get(id)?.death)
  const allDeceased = partnerIds.every((id) => personById.get(id)?.death)
  return anyDeceased && !allDeceased ? "widowed" : "married"
}

/**
 * Parent links must form a DAG or generation assignment never terminates.
 * Cuts the back-edge of any cycle and reports it.
 */
function breakParentCycles(
  people: Person[],
  parentsOf: Map<string, string[]>,
  personById: Map<string, Person>,
  diagnostics: Diagnostic[]
) {
  const WHITE = 0
  const GREY = 1
  const BLACK = 2
  const colour = new Map<string, number>(people.map((p) => [p.id, WHITE]))

  const visit = (id: string) => {
    colour.set(id, GREY)
    const parents = parentsOf.get(id) ?? []
    const kept: string[] = []

    for (const parentId of parents) {
      const state = colour.get(parentId) ?? WHITE
      if (state === GREY) {
        diagnostics.push({
          code: "parent-cycle",
          personId: id,
          message: `Ancestry cycle through "${
            personById.get(parentId)?.name ?? parentId
          }"; that parent link was dropped.`,
        })
        continue // drop the back-edge
      }
      if (state === WHITE) visit(parentId)
      kept.push(parentId)
    }

    parentsOf.set(id, kept)
    colour.set(id, BLACK)
  }

  for (const person of people) {
    if (colour.get(person.id) === WHITE) visit(person.id)
  }
}

import type { FamilyGraph } from "./types"

const MAX_PASSES = 64

/**
 * Assigns every person a generation index, where 0 is the oldest generation
 * present and larger numbers are further down.
 *
 * A single BFS is not enough: cousin marriages and uncle/niece unions give the
 * same person two different depths depending on the path taken. Instead we
 * relax to a fixpoint over two rules, which always converges upward and so
 * terminates once the parent graph is acyclic (`buildGraph` guarantees that):
 *
 *   1. a child sits strictly below its lowest parent
 *   2. partners share a generation, taking the lower of the two
 */
export function assignGenerations(graph: FamilyGraph): Map<string, number> {
  const generation = new Map<string, number>(
    graph.people.map((person) => [person.id, 0])
  )

  for (let pass = 0; pass < MAX_PASSES; pass++) {
    let changed = false

    for (const person of graph.people) {
      const parents = graph.parentsOf.get(person.id) ?? []
      if (parents.length === 0) continue

      let lowestParent = -Infinity
      for (const parentId of parents) {
        lowestParent = Math.max(lowestParent, generation.get(parentId) ?? 0)
      }

      const target = lowestParent + 1
      if (target > (generation.get(person.id) ?? 0)) {
        generation.set(person.id, target)
        changed = true
      }
    }

    for (const union of graph.unions) {
      let lowest = -Infinity
      for (const partnerId of union.partnerIds) {
        lowest = Math.max(lowest, generation.get(partnerId) ?? 0)
      }
      for (const partnerId of union.partnerIds) {
        if ((generation.get(partnerId) ?? 0) < lowest) {
          generation.set(partnerId, lowest)
          changed = true
        }
      }
    }

    if (!changed) break
  }

  normaliseToZero(generation)
  return generation
}

/**
 * Shifts each connected component so the whole tree starts at generation 0.
 * Components are normalised independently — two unrelated families should both
 * begin at the top rather than one floating below the other.
 */
function normaliseToZero(generation: Map<string, number>) {
  let min = Number.POSITIVE_INFINITY
  for (const value of generation.values()) min = Math.min(min, value)
  if (min === 0 || !Number.isFinite(min)) return
  for (const [id, value] of generation) generation.set(id, value - min)
}

/**
 * Splits the graph into connected components (following parent, child and
 * partner links alike), in input order. Layout places these side by side.
 */
export function findComponents(graph: FamilyGraph): string[][] {
  const seen = new Set<string>()
  const components: string[][] = []

  for (const person of graph.people) {
    if (seen.has(person.id)) continue

    const component: string[] = []
    const queue = [person.id]
    seen.add(person.id)

    while (queue.length > 0) {
      const id = queue.shift()!
      component.push(id)

      const neighbours = [
        ...(graph.parentsOf.get(id) ?? []),
        ...(graph.childrenOf.get(id) ?? []),
        ...(graph.partnersOf.get(id) ?? []),
      ]

      for (const neighbour of neighbours) {
        if (seen.has(neighbour)) continue
        seen.add(neighbour)
        queue.push(neighbour)
      }
    }

    components.push(component)
  }

  return components
}

import { assignGenerations, findComponents } from "./generations"
import type {
  FamilyGraph,
  GenerationRow,
  LayoutNode,
  LayoutOptions,
  TreeLayout,
  Union,
  UnionAnchor,
} from "./types"

export const DEFAULT_LAYOUT_OPTIONS: LayoutOptions = {
  cardWidth: 200,
  cardHeight: 78,
  partnerGap: 28,
  siblingGap: 32,
  componentGap: 96,
  rowGap: 72,
}

/**
 * A person plus the partners who sit beside them — the unit the tidy pass moves
 * around. Rendering one person once, with successive spouses flanking them,
 * is what keeps remarriages readable.
 */
interface Cluster {
  /** The person this cluster is anchored on (the one with descent into it). */
  anchorId: string
  /** Anchor plus partners, left to right. */
  memberIds: string[]
  generation: number
  /** Unions whose children hang below this cluster, in placement order. */
  unions: Union[]
  width: number
  /** Left edge, filled in by the tidy pass. */
  x: number
}

export function layoutTree(
  graph: FamilyGraph,
  options: Partial<LayoutOptions> = {}
): TreeLayout {
  const opts = { ...DEFAULT_LAYOUT_OPTIONS, ...options }
  const generation = assignGenerations(graph)

  const { clusters, clusterOf } = buildClusters(graph, generation, opts)

  /* ------------------------- tidy pass, per component ------------------------ */

  let cursor = 0

  for (const component of findComponents(graph)) {
    const memberSet = new Set(component)
    const roots = componentRoots(graph, clusters, memberSet)
    const placed = new Set<string>()

    let componentLeft = cursor
    for (const root of roots) {
      const width = placeSubtree(root, componentLeft, {
        graph,
        clusterOf,
        placed,
        opts,
      })
      componentLeft += width + opts.siblingGap
    }

    // Anything the walk missed (a spouse whose own ancestry sits elsewhere)
    // gets parked to the right rather than stacking at zero.
    for (const cluster of clusters) {
      if (!memberSet.has(cluster.anchorId) || placed.has(cluster.anchorId))
        continue
      cluster.x = componentLeft
      placed.add(cluster.anchorId)
      componentLeft += cluster.width + opts.siblingGap
    }

    cursor = componentLeft + opts.componentGap
  }

  /* ---------------------------- resolve overlaps ---------------------------- */

  // `placeSubtree` already centres every couple over their children, so the
  // only job left is to pull apart clusters that the walk placed independently.
  // Separation shifts whole subtrees rigidly, which keeps that centring intact
  // instead of undoing it — the alternative, alternating separate/re-centre
  // passes, leaves parents visibly off-centre wherever the two disagree.
  settle(clusters, clusterOf, opts)

  /* ------------------------------ emit nodes ------------------------------- */

  return emit(graph, clusters, generation, opts)
}

/* -------------------------------------------------------------------------- */
/*                              Cluster building                              */
/* -------------------------------------------------------------------------- */

function buildClusters(
  graph: FamilyGraph,
  generation: Map<string, number>,
  opts: LayoutOptions
) {
  const clusters: Cluster[] = []
  const clusterOf = new Map<string, Cluster>()
  const claimed = new Set<string>()

  // Anchor on people who descend from somewhere in the tree, oldest first, so
  // that a person who married in attaches to their spouse rather than the
  // other way round.
  const ordered = [...graph.people].sort(
    (a, b) => (generation.get(a.id) ?? 0) - (generation.get(b.id) ?? 0)
  )

  const descends = (id: string) => (graph.parentsOf.get(id) ?? []).length > 0

  for (const person of ordered) {
    if (claimed.has(person.id)) continue

    // Walk the chain of partners rightward: the anchor, their spouse, that
    // spouse's next spouse, and so on. A remarriage reads as one run of cards
    // (Edith | Felix | Nadia), which is the only arrangement where both of
    // Felix's unions can drop their connectors from between the right pair.
    const memberIds: string[] = [person.id]
    claimed.add(person.id)

    // Index-based on purpose: the loop appends to `memberIds` as it discovers
    // further spouses, and must visit those too.
    // eslint-disable-next-line @typescript-eslint/prefer-for-of
    for (let i = 0; i < memberIds.length; i++) {
      const currentId = memberIds[i]
      for (const union of graph.unionsByPartner.get(currentId) ?? []) {
        for (const partnerId of union.partnerIds) {
          if (partnerId === currentId || claimed.has(partnerId)) continue
          // Anyone with their own ancestry needs their own cluster so their
          // parents can sit above them. Only people who married in join.
          if (descends(partnerId)) continue
          memberIds.push(partnerId)
          claimed.add(partnerId)
        }
      }
    }

    // Every union any member belongs to hangs off this cluster.
    const unions = [
      ...new Set(
        memberIds.flatMap((id) => graph.unionsByPartner.get(id) ?? [])
      ),
    ]

    const cluster: Cluster = {
      anchorId: person.id,
      memberIds,
      generation: generation.get(person.id) ?? 0,
      unions,
      width:
        memberIds.length * opts.cardWidth +
        (memberIds.length - 1) * opts.partnerGap,
      x: 0,
    }

    clusters.push(cluster)
    for (const id of memberIds) clusterOf.set(id, cluster)
  }

  return { clusters, clusterOf }
}

/** Clusters in this component with no parent inside it — the tops of the walk. */
function componentRoots(
  graph: FamilyGraph,
  clusters: Cluster[],
  memberSet: Set<string>
): Cluster[] {
  const roots = clusters.filter((cluster) => {
    if (!memberSet.has(cluster.anchorId)) return false
    return cluster.memberIds.every(
      (id) => (graph.parentsOf.get(id) ?? []).length === 0
    )
  })

  if (roots.length > 0) return roots

  // Every cluster has a parent — a fully connected cycle would have been cut in
  // `buildGraph`, so this only happens for odd inputs. Fall back to the topmost.
  const candidates = clusters
    .filter((c) => memberSet.has(c.anchorId))
    .sort((a, b) => a.generation - b.generation)
  return candidates.slice(0, 1)
}

/* -------------------------------------------------------------------------- */
/*                                 Tidy pass                                  */
/* -------------------------------------------------------------------------- */

interface WalkContext {
  graph: FamilyGraph
  clusterOf: Map<string, Cluster>
  placed: Set<string>
  opts: LayoutOptions
}

/**
 * Classic post-order tidy: lay the children out left to right, then centre the
 * parent over the span they occupy. Returns the width consumed.
 */
function placeSubtree(
  cluster: Cluster,
  left: number,
  ctx: WalkContext
): number {
  if (ctx.placed.has(cluster.anchorId)) return 0
  ctx.placed.add(cluster.anchorId)

  const childClusters: Cluster[] = []
  for (const union of cluster.unions) {
    for (const childId of union.childIds) {
      const child = ctx.clusterOf.get(childId)
      if (!child || ctx.placed.has(child.anchorId)) continue
      childClusters.push(child)
    }
  }

  if (childClusters.length === 0) {
    cluster.x = left
    return cluster.width
  }

  let childLeft = left
  for (const child of childClusters) {
    const consumed = placeSubtree(child, childLeft, ctx)
    childLeft += consumed + ctx.opts.siblingGap
  }

  const childrenWidth = childLeft - ctx.opts.siblingGap - left

  // Line the connectors up with the middle of the children's *cards*, not with
  // the middle of their subtrees — a child whose own spouse widens their
  // cluster would otherwise drag the parent sideways.
  let min = Number.POSITIVE_INFINITY
  let max = Number.NEGATIVE_INFINITY
  for (const union of cluster.unions) {
    for (const childId of union.childIds) {
      const centre = cardCentre(childId, ctx.clusterOf, ctx.opts)
      if (centre === null) continue
      min = Math.min(min, centre)
      max = Math.max(max, centre)
    }
  }

  if (Number.isFinite(min)) {
    // Averaged across the cluster's unions: someone with two marriages cannot
    // sit over both sets of children, so the layout splits the difference.
    cluster.x = (min + max) / 2 - anchorOffset(cluster, ctx.opts)
  }

  if (cluster.x < left) {
    // The couple is wider than its children; shift the children right rather
    // than let the parent hang off the left edge of its own subtree.
    const delta = left - cluster.x
    cluster.x = left
    for (const child of childClusters) shiftSubtree(child, delta, ctx.clusterOf)
    return Math.max(childrenWidth + delta, cluster.width)
  }

  return Math.max(childrenWidth, cluster.width)
}

/** Centre of a person's card at the cluster's current position. */
function cardCentre(
  personId: string,
  clusterOf: Map<string, Cluster>,
  opts: LayoutOptions
): number | null {
  const cluster = clusterOf.get(personId)
  if (!cluster) return null
  const index = cluster.memberIds.indexOf(personId)
  if (index < 0) return null
  return (
    cluster.x + index * (opts.cardWidth + opts.partnerGap) + opts.cardWidth / 2
  )
}

/**
 * Distance from a cluster's left edge to the point its descent connectors drop
 * from, averaged over every union in the cluster. For a plain couple that is
 * the midpoint between the two cards; for a remarriage chain it is the mean of
 * the two union midpoints, so the cluster straddles both sets of children.
 */
function anchorOffset(cluster: Cluster, opts: LayoutOptions): number {
  const step = opts.cardWidth + opts.partnerGap
  const localCentre = (personId: string) => {
    const index = cluster.memberIds.indexOf(personId)
    return index < 0 ? null : index * step + opts.cardWidth / 2
  }

  const offsets: number[] = []
  for (const union of cluster.unions) {
    if (union.childIds.length === 0) continue
    const centres = union.partnerIds
      .map(localCentre)
      .filter((x): x is number => x !== null)
    if (centres.length === 0) continue
    offsets.push(centres.reduce((sum, x) => sum + x, 0) / centres.length)
  }

  if (offsets.length === 0) {
    // No children to line up with; fall back to the middle of the cluster.
    return (cluster.memberIds.length - 1) * step * 0.5 + opts.cardWidth / 2
  }

  return offsets.reduce((sum, x) => sum + x, 0) / offsets.length
}

/** Moves a cluster and everything descending from it by the same amount. */
function shiftSubtree(
  cluster: Cluster,
  delta: number,
  clusterOf: Map<string, Cluster>,
  seen: Set<Cluster> = new Set()
) {
  if (delta === 0 || seen.has(cluster)) return
  seen.add(cluster)
  cluster.x += delta

  for (const union of cluster.unions) {
    for (const childId of union.childIds) {
      const child = clusterOf.get(childId)
      if (child && child !== cluster)
        shiftSubtree(child, delta, clusterOf, seen)
    }
  }
}

function groupByGeneration(clusters: Cluster[]): Map<number, Cluster[]> {
  const byGeneration = new Map<number, Cluster[]>()
  for (const cluster of clusters) {
    const list = byGeneration.get(cluster.generation)
    if (list) list.push(cluster)
    else byGeneration.set(cluster.generation, [cluster])
  }
  return byGeneration
}

/**
 * Pulls apart clusters that overlap within a generation, top-down, repeating
 * until nothing moves. A cluster that has to move takes its whole subtree with
 * it, so the couple-over-children alignment established during the walk
 * survives; only the gaps between independent subtrees grow.
 */
function settle(
  clusters: Cluster[],
  clusterOf: Map<string, Cluster>,
  opts: LayoutOptions
) {
  const byGeneration = groupByGeneration(clusters)
  const generations = [...byGeneration.keys()].sort((a, b) => a - b)

  for (let pass = 0; pass < 8; pass++) {
    let moved = false

    for (const gen of generations) {
      const row = byGeneration.get(gen)!
      row.sort((a, b) => a.x - b.x)

      let edge = -Infinity
      for (const cluster of row) {
        if (cluster.x < edge) {
          shiftSubtree(cluster, edge - cluster.x, clusterOf)
          moved = true
        }
        edge = cluster.x + cluster.width + opts.siblingGap
      }
    }

    if (!moved) return
  }
}

/* -------------------------------------------------------------------------- */
/*                                   Emit                                     */
/* -------------------------------------------------------------------------- */

function emit(
  graph: FamilyGraph,
  clusters: Cluster[],
  generation: Map<string, number>,
  opts: LayoutOptions
): TreeLayout {
  const nodes: LayoutNode[] = []
  const nodeById = new Map<string, LayoutNode>()
  const rowHeight = opts.cardHeight + opts.rowGap

  for (const cluster of clusters) {
    cluster.memberIds.forEach((personId, index) => {
      const node: LayoutNode = {
        personId,
        generation: cluster.generation,
        x: cluster.x + index * (opts.cardWidth + opts.partnerGap),
        y: cluster.generation * rowHeight,
        width: opts.cardWidth,
        height: opts.cardHeight,
      }
      nodes.push(node)
      nodeById.set(personId, node)
    })
  }

  // Shift everything so the tree starts at the origin.
  const minX = Math.min(...nodes.map((n) => n.x), 0)
  if (minX !== 0) {
    for (const node of nodes) node.x -= minX
    for (const cluster of clusters) cluster.x -= minX
  }

  /* ------------------------------ union anchors ----------------------------- */

  const unions: UnionAnchor[] = []

  for (const union of graph.unions) {
    const partnerPoints = union.partnerIds
      .map((personId) => nodeById.get(personId))
      .filter((node): node is LayoutNode => Boolean(node))
      .map((node) => ({
        personId: node.personId,
        x: node.x + node.width / 2,
        y: node.y + node.height / 2,
      }))

    if (partnerPoints.length === 0) continue

    const childPoints = union.childIds
      .map((personId) => nodeById.get(personId))
      .filter((node): node is LayoutNode => Boolean(node))
      .map((node) => ({
        personId: node.personId,
        x: node.x + node.width / 2,
        y: node.y,
      }))

    const partnerGeneration = generation.get(union.partnerIds[0]) ?? 0
    const anchorX =
      partnerPoints.reduce((sum, p) => sum + p.x, 0) / partnerPoints.length
    // Drop from the bottom edge of the partners' row, not their mid-height.
    const anchorY = partnerGeneration * rowHeight + opts.cardHeight

    unions.push({
      unionId: union.id,
      generation: partnerGeneration,
      x: anchorX,
      y: anchorY,
      partnerPoints,
      childPoints,
    })
  }

  /* ------------------------------- generations ------------------------------ */

  const rowMap = new Map<number, string[]>()
  for (const node of nodes) {
    const list = rowMap.get(node.generation)
    if (list) list.push(node.personId)
    else rowMap.set(node.generation, [node.personId])
  }

  const generations: GenerationRow[] = [...rowMap.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([gen, personIds]) => ({
      generation: gen,
      y: gen * rowHeight,
      height: opts.cardHeight,
      personIds: personIds.sort(
        (a, b) => (nodeById.get(a)?.x ?? 0) - (nodeById.get(b)?.x ?? 0)
      ),
    }))

  const maxX = Math.max(...nodes.map((n) => n.x + n.width), 0)
  const maxY = Math.max(...nodes.map((n) => n.y + n.height), 0)

  return {
    nodes,
    nodeById,
    unions,
    generations,
    bounds: { x: 0, y: 0, width: maxX, height: maxY },
  }
}

import type {
  FamilyGraph,
  Person,
  Relationship,
  RelationshipType,
  Sex,
} from "./types"

/* -------------------------------------------------------------------------- */
/*                                   Wording                                  */
/* -------------------------------------------------------------------------- */

type Gendered = { male: string; female: string; neutral: string }

const TERMS: Record<string, Gendered> = {
  parent: { male: "father", female: "mother", neutral: "parent" },
  child: { male: "son", female: "daughter", neutral: "child" },
  sibling: { male: "brother", female: "sister", neutral: "sibling" },
  partner: { male: "husband", female: "wife", neutral: "partner" },
  pibling: { male: "uncle", female: "aunt", neutral: "aunt or uncle" },
  nibling: { male: "nephew", female: "niece", neutral: "nibling" },
  grandparent: {
    male: "grandfather",
    female: "grandmother",
    neutral: "grandparent",
  },
  grandchild: {
    male: "grandson",
    female: "granddaughter",
    neutral: "grandchild",
  },
}

function term(key: keyof typeof TERMS, sex: Sex): string {
  const entry = TERMS[key]
  return sex === "male"
    ? entry.male
    : sex === "female"
      ? entry.female
      : entry.neutral
}

const ORDINALS = [
  "first",
  "second",
  "third",
  "fourth",
  "fifth",
  "sixth",
  "seventh",
  "eighth",
  "ninth",
  "tenth",
]

function ordinal(n: number): string {
  return ORDINALS[n - 1] ?? `${n}th`
}

/** "once removed", "twice removed", "3× removed". */
function removedSuffix(removed: number): string {
  if (removed === 0) return ""
  if (removed === 1) return " once removed"
  if (removed === 2) return " twice removed"
  if (removed === 3) return " three times removed"
  return ` ${removed}× removed`
}

/** 1 → "", 2 → "grand", 3 → "great-grand", 4 → "great-great-grand". */
function grandPrefix(steps: number): string {
  if (steps <= 1) return ""
  if (steps === 2) return "grand"
  return `${"great-".repeat(steps - 2)}grand`
}

/* -------------------------------------------------------------------------- */
/*                                  Ancestry                                  */
/* -------------------------------------------------------------------------- */

/**
 * Every ancestor of `id` mapped to its distance in generations. When a person
 * is reachable by more than one path (cousin marriage, pedigree collapse) the
 * shortest distance wins, which is the convention genealogists use.
 */
export function ancestorsOf(
  graph: FamilyGraph,
  id: string,
  cache?: Map<string, Map<string, number>>
): Map<string, number> {
  const cached = cache?.get(id)
  if (cached) return cached

  const distances = new Map<string, number>()
  let frontier = [id]
  let depth = 0

  while (frontier.length > 0 && depth < 64) {
    depth++
    const next: string[] = []

    for (const current of frontier) {
      for (const parentId of graph.parentsOf.get(current) ?? []) {
        if (distances.has(parentId)) continue
        distances.set(parentId, depth)
        next.push(parentId)
      }
    }

    frontier = next
  }

  cache?.set(id, distances)
  return distances
}

/** All descendants of `id` mapped to their distance in generations. */
export function descendantsOf(
  graph: FamilyGraph,
  id: string
): Map<string, number> {
  const distances = new Map<string, number>()
  let frontier = [id]
  let depth = 0

  while (frontier.length > 0 && depth < 64) {
    depth++
    const next: string[] = []

    for (const current of frontier) {
      for (const childId of graph.childrenOf.get(current) ?? []) {
        if (distances.has(childId)) continue
        distances.set(childId, depth)
        next.push(childId)
      }
    }

    frontier = next
  }

  return distances
}

/* -------------------------------------------------------------------------- */
/*                            Relationship calculus                           */
/* -------------------------------------------------------------------------- */

export interface KinshipContext {
  ancestorCache: Map<string, Map<string, number>>
}

export function createKinshipContext(): KinshipContext {
  return { ancestorCache: new Map() }
}

const UNRELATED: Relationship = {
  type: "unrelated",
  kind: "none",
  label: "",
}

/**
 * Names `to`'s relationship as seen from `from` — the label answers
 * "who is this person to me?", so `relationshipTo(graph, me, x).label === "father"`
 * means x is my father.
 *
 * Resolution order: self, partner, direct line, common ancestor, step, in-law.
 * In-law is tried last because a blood link, however distant, is the more
 * informative answer whenever both exist.
 */
export function relationshipTo(
  graph: FamilyGraph,
  fromId: string,
  toId: string,
  ctx: KinshipContext = createKinshipContext()
): Relationship {
  const from = graph.personById.get(fromId)
  const to = graph.personById.get(toId)
  if (!from || !to) return UNRELATED

  if (fromId === toId) {
    return { type: "self", kind: "self", label: "you" }
  }

  const direct = bloodRelationship(graph, fromId, toId, ctx)
  if (direct) return direct

  const partner = partnerRelationship(graph, fromId, toId)
  if (partner) return partner

  const step = stepRelationship(graph, fromId, toId)
  if (step) return step

  const inLaw = inLawRelationship(graph, fromId, toId, ctx)
  if (inLaw) return inLaw

  return UNRELATED
}

function partnerRelationship(
  graph: FamilyGraph,
  fromId: string,
  toId: string
): Relationship | null {
  const unions = graph.unionsByPartner.get(fromId) ?? []
  const shared = unions.find((union) => union.partnerIds.includes(toId))
  if (!shared) return null

  const to = graph.personById.get(toId)!
  const ended = shared.status === "divorced" || shared.status === "separated"
  const base = term("partner", to.sex)

  if (shared.status === "widowed") {
    return {
      type: "partner",
      kind: "affinal",
      label: to.death ? `late ${base}` : base,
    }
  }

  return {
    type: ended ? "ex-partner" : "partner",
    kind: "affinal",
    label: ended ? `ex-${base}` : base,
  }
}

function bloodRelationship(
  graph: FamilyGraph,
  fromId: string,
  toId: string,
  ctx: KinshipContext
): Relationship | null {
  const fromAncestors = ancestorsOf(graph, fromId, ctx.ancestorCache)
  const toAncestors = ancestorsOf(graph, toId, ctx.ancestorCache)
  const to = graph.personById.get(toId)!
  const from = graph.personById.get(fromId)!

  // `to` is my ancestor.
  const upSteps = fromAncestors.get(toId)
  if (upSteps !== undefined) {
    const key = upSteps === 1 ? "parent" : "grandparent"
    const label =
      upSteps === 1
        ? term("parent", to.sex)
        : grandPrefix(upSteps) + term("parent", to.sex)
    return {
      type: key === "parent" ? "parent" : "grandparent",
      kind: "blood",
      steps: upSteps,
      label,
    }
  }

  // `to` is my descendant.
  const downSteps = toAncestors.get(fromId)
  if (downSteps !== undefined) {
    const label =
      downSteps === 1
        ? term("child", to.sex)
        : grandPrefix(downSteps) + term("child", to.sex)
    return {
      type: downSteps === 1 ? "child" : "grandchild",
      kind: "blood",
      steps: downSteps,
      label,
    }
  }

  // Collateral: find the common ancestor minimising (myDepth, theirDepth).
  let best: { mine: number; theirs: number } | null = null
  for (const [ancestorId, mine] of fromAncestors) {
    const theirs = toAncestors.get(ancestorId)
    if (theirs === undefined) continue
    if (
      !best ||
      mine + theirs < best.mine + best.theirs ||
      (mine + theirs === best.mine + best.theirs &&
        Math.abs(mine - theirs) < Math.abs(best.mine - best.theirs))
    ) {
      best = { mine, theirs }
    }
  }

  if (!best) return null

  const { mine, theirs } = best

  // Siblings.
  if (mine === 1 && theirs === 1) {
    const myParents = new Set(graph.parentsOf.get(fromId) ?? [])
    const theirParents = graph.parentsOf.get(toId) ?? []
    const shared = theirParents.filter((id) => myParents.has(id)).length
    const full = shared >= 2
    return {
      type: full ? "sibling" : "half-sibling",
      kind: "blood",
      label: full ? term("sibling", to.sex) : `half-${term("sibling", to.sex)}`,
    }
  }

  // Aunt / uncle and their greats: they are one step below our common ancestor.
  if (theirs === 1) {
    const prefix = "great-".repeat(mine - 2)
    return {
      type: "pibling",
      kind: "blood",
      removed: mine - 2,
      label: prefix + term("pibling", to.sex),
    }
  }

  // Niece / nephew and their greats.
  if (mine === 1) {
    const prefix =
      theirs === 2
        ? ""
        : theirs === 3
          ? "grand-"
          : "great-".repeat(theirs - 3) + "grand-"
    return {
      type: "nibling",
      kind: "blood",
      removed: theirs - 2,
      label: prefix + term("nibling", to.sex),
    }
  }

  // Cousins.
  const degree = Math.min(mine, theirs) - 1
  const removed = Math.abs(mine - theirs)
  void from
  return {
    type: "cousin",
    kind: "blood",
    degree,
    removed,
    label: `${ordinal(degree)} cousin${removedSuffix(removed)}`,
  }
}

/**
 * A step relation runs through a parent's other partner: my parent's spouse who
 * is not my parent is my step-parent, and their children by another union are my
 * step-siblings.
 */
function stepRelationship(
  graph: FamilyGraph,
  fromId: string,
  toId: string
): Relationship | null {
  const myParents = graph.parentsOf.get(fromId) ?? []
  const to = graph.personById.get(toId)!

  const stepParents = new Set<string>()
  for (const parentId of myParents) {
    for (const union of graph.unionsByPartner.get(parentId) ?? []) {
      for (const partnerId of union.partnerIds) {
        if (partnerId !== parentId && !myParents.includes(partnerId)) {
          stepParents.add(partnerId)
        }
      }
    }
  }

  if (stepParents.has(toId)) {
    return {
      type: "parent",
      kind: "step",
      steps: 1,
      label: `step-${term("parent", to.sex)}`,
    }
  }

  // Children of a step-parent, by any union that isn't shared with my parent.
  for (const stepParentId of stepParents) {
    if ((graph.childrenOf.get(stepParentId) ?? []).includes(toId)) {
      return {
        type: "sibling",
        kind: "step",
        label: `step-${term("sibling", to.sex)}`,
      }
    }
  }

  // Mirror: my partner's child from another union is my step-child.
  for (const union of graph.unionsByPartner.get(fromId) ?? []) {
    for (const partnerId of union.partnerIds) {
      if (partnerId === fromId) continue
      const theirChildren = graph.childrenOf.get(partnerId) ?? []
      const mine = graph.childrenOf.get(fromId) ?? []
      if (theirChildren.includes(toId) && !mine.includes(toId)) {
        return {
          type: "child",
          kind: "step",
          steps: 1,
          label: `step-${term("child", to.sex)}`,
        }
      }
    }
  }

  return null
}

/**
 * Marriage-based links, tried only once blood and step have failed. Two routes:
 * the blood relative of my partner, or the partner of my blood relative.
 */
function inLawRelationship(
  graph: FamilyGraph,
  fromId: string,
  toId: string,
  ctx: KinshipContext
): Relationship | null {
  const to = graph.personById.get(toId)!

  // Route 1 — my partner's relative. "my wife's mother" -> mother-in-law.
  for (const partnerId of graph.partnersOf.get(fromId) ?? []) {
    const via = bloodRelationship(graph, partnerId, toId, ctx)
    if (via) return asInLaw(via)
  }

  // Route 2 — my relative's partner. "my sister's husband" -> brother-in-law.
  for (const theirPartnerId of graph.partnersOf.get(toId) ?? []) {
    const via = bloodRelationship(graph, fromId, theirPartnerId, ctx)
    if (via) return asInLaw(via, to.sex)
  }

  return null
}

/**
 * Converts a blood term to its in-law form. When `sex` is given the term is
 * re-gendered for the in-law themselves — my sister's husband is a
 * brother-in-law, not a sister-in-law.
 */
function asInLaw(relationship: Relationship, sex?: Sex): Relationship {
  const label = sex ? regender(relationship, sex) : relationship.label
  return {
    ...relationship,
    kind: "affinal",
    inLaw: true,
    label: `${label}-in-law`,
  }
}

function regender(relationship: Relationship, sex: Sex): string {
  const key: Record<RelationshipType, keyof typeof TERMS | null> = {
    self: null,
    partner: "partner",
    "ex-partner": "partner",
    parent: "parent",
    child: "child",
    sibling: "sibling",
    "half-sibling": "sibling",
    grandparent: "grandparent",
    grandchild: "grandchild",
    pibling: "pibling",
    nibling: "nibling",
    cousin: null,
    unrelated: null,
  }

  const termKey = key[relationship.type]
  if (!termKey) return relationship.label

  // Preserve any prefix ("great-", "grand") that the blood label carried.
  const base = term(termKey, sex)
  const match = /^((?:great-)*(?:grand-?)?)/.exec(relationship.label)
  return (match?.[1] ?? "") + base
}

/** Convenience wrapper used by the card renderer. */
export function relationshipLabel(
  graph: FamilyGraph,
  fromId: string,
  toId: string,
  ctx?: KinshipContext
): string {
  return relationshipTo(graph, fromId, toId, ctx).label
}

export type { Person }

import { ancestorsOf, descendantsOf } from "./kinship"
import type { BranchAssignment, FamilyGraph } from "./types"

/** How many distinct branch hues the palette provides. */
export const BRANCH_SLOTS = 8

/** Slots 0-3 are the four grandparent lines; 4 is the focus person's own line. */
const OWN_LINE_SLOT = 4

/**
 * Assigns a colour slot to each person, relative to the person in focus.
 *
 * The four grandparent lines seed slots 0-3, in the order paternal-paternal,
 * paternal-maternal, maternal-paternal, maternal-maternal — the quadrants of a
 * pedigree chart. Colour is decided by the *path* taken from the focus person
 * upwards, so a great-grandparent five steps up still carries the hue of the
 * quadrant you reach them through.
 *
 * Everyone who is not a direct ancestor takes the hue of the line they share
 * with the focus person: an aunt through the paternal grandparents reads as
 * paternal, a cousin through the maternal ones as maternal. The focus person
 * and their descendants get a line of their own, because they descend from all
 * four quadrants and picking one would be arbitrary.
 *
 * The net effect is that the palette always answers the same question — which
 * side of *your* family is this? — from wherever you are standing.
 */
export function assignBranches(
  graph: FamilyGraph,
  focusId: string | null
): BranchAssignment {
  const branchOf = new Map<string, number>()
  const seeds: BranchAssignment["seeds"] = []

  if (!focusId || !graph.personById.has(focusId)) {
    return applyOverrides(graph, branchOf, seeds)
  }

  /* --------------------- 1. the focus person's own line --------------------- */

  branchOf.set(focusId, OWN_LINE_SLOT)
  for (const descendantId of descendantsOf(graph, focusId).keys()) {
    branchOf.set(descendantId, OWN_LINE_SLOT)
  }
  seeds.push({
    slot: OWN_LINE_SLOT,
    personId: focusId,
    label: graph.personById.get(focusId)?.name ?? focusId,
  })

  /* ------------------------ 2. the ancestral quadrants ---------------------- */

  // Breadth-first up the pedigree, carrying the path taken to get there. The
  // first two steps of that path are what pick the quadrant.
  const quadrantOf = new Map<string, number>()
  let frontier: Array<{ id: string; path: number[] }> = [
    { id: focusId, path: [] },
  ]

  while (frontier.length > 0) {
    const next: Array<{ id: string; path: number[] }> = []

    for (const { id, path } of frontier) {
      const parents = graph.parentsOf.get(id) ?? []

      parents.forEach((parentId, index) => {
        if (quadrantOf.has(parentId)) return

        const nextPath = [...path, index]
        // A parent shares the hue of their own first parent's quadrant; from
        // the grandparents up, the first two steps name the quadrant outright.
        const slot =
          nextPath.length === 1
            ? nextPath[0] * 2
            : nextPath[0] * 2 + nextPath[1]

        quadrantOf.set(parentId, Math.min(slot, 3))
        next.push({ id: parentId, path: nextPath })
      })
    }

    frontier = next
  }

  for (const [personId, slot] of quadrantOf) {
    if (!branchOf.has(personId)) branchOf.set(personId, slot)
  }

  // Name each quadrant after the oldest person heading it, for a legend.
  for (const slot of [0, 1, 2, 3]) {
    const head = [...quadrantOf.entries()].find(([, value]) => value === slot)
    if (!head) continue
    seeds.push({
      slot,
      personId: head[0],
      label: graph.personById.get(head[0])?.name ?? head[0],
    })
  }

  /* ------------------- 3. everyone else, by shared ancestry ------------------ */

  for (const person of graph.people) {
    if (branchOf.has(person.id)) continue

    // The closest ancestor this person shares with one of the focus person's
    // lines decides their colour — that is the branch they hang off.
    let best: { depth: number; slot: number } | null = null
    for (const [ancestorId, depth] of ancestorsOf(graph, person.id)) {
      const slot = quadrantOf.get(ancestorId)
      if (slot === undefined) continue
      if (
        !best ||
        depth < best.depth ||
        (depth === best.depth && slot < best.slot)
      ) {
        best = { depth, slot }
      }
    }

    if (best) branchOf.set(person.id, best.slot)
  }

  /* ------------------------- 4. partners join in ---------------------------- */

  // Someone who married in has no line of their own; taking their spouse's
  // keeps a couple reading as one unit rather than two unrelated cards.
  for (const union of graph.unions) {
    const slots = union.partnerIds
      .map((id) => branchOf.get(id))
      .filter((slot): slot is number => slot !== undefined)
    if (slots.length === 0) continue
    for (const partnerId of union.partnerIds) {
      if (!branchOf.has(partnerId)) branchOf.set(partnerId, Math.min(...slots))
    }
  }

  return applyOverrides(graph, branchOf, seeds)
}

/** An explicit `branchId` always wins over the computed assignment. */
function applyOverrides(
  graph: FamilyGraph,
  branchOf: Map<string, number>,
  seeds: BranchAssignment["seeds"]
): BranchAssignment {
  const manual = new Map<string, number>()

  for (const person of graph.people) {
    if (!person.branchId) continue
    if (!manual.has(person.branchId)) manual.set(person.branchId, manual.size)
    branchOf.set(person.id, manual.get(person.branchId)! % BRANCH_SLOTS)
  }

  return { branchOf, seeds }
}

import { ancestorsOf, descendantsOf } from "./kinship"
import type { FamilyGraph, Lineage } from "./types"

/**
 * The set of people considered "on the focus person's line": everyone above
 * them, everyone below them, their partners and their siblings.
 *
 * Drives both the dimming in `highlight` mode and the filter in `isolate` mode.
 */
export function lineageOf(graph: FamilyGraph, focusId: string): Lineage {
  const ancestors = new Set(ancestorsOf(graph, focusId).keys())
  const descendants = new Set(descendantsOf(graph, focusId).keys())
  const partners = new Set(graph.partnersOf.get(focusId) ?? [])

  const siblings = new Set<string>()
  for (const parentId of graph.parentsOf.get(focusId) ?? []) {
    for (const childId of graph.childrenOf.get(parentId) ?? []) {
      if (childId !== focusId) siblings.add(childId)
    }
  }

  const all = new Set<string>([focusId])
  for (const set of [ancestors, descendants, partners, siblings]) {
    for (const id of set) all.add(id)
  }

  // Ancestors' and descendants' partners come along too — a grandmother
  // without her husband beside her reads as an error rather than a filter.
  for (const id of [...ancestors, ...descendants]) {
    for (const partnerId of graph.partnersOf.get(id) ?? []) all.add(partnerId)
  }

  return { focusId, ancestors, descendants, partners, siblings, all }
}

import * as React from "react"
import { assignBranches } from "./branches"
import { buildGraph } from "./graph"
import { createKinshipContext, relationshipTo } from "./kinship"
import { layoutTree } from "./layout"
import { lineageOf } from "./lineage"
import type {
  FamilyGraph,
  LayoutOptions,
  Lineage,
  Person,
  Relationship,
  TreeLayout,
} from "./types"

export type FocusMode = "highlight" | "isolate"

export interface UseFamilyTreeOptions {
  people: Person[]
  focusId: string | null
  focusMode?: FocusMode
  layout?: Partial<LayoutOptions>
}

export interface FamilyTreeModel {
  /** The full graph, before any focus filtering. */
  graph: FamilyGraph
  /** The graph actually rendered — filtered in `isolate` mode. */
  visibleGraph: FamilyGraph
  layout: TreeLayout
  lineage: Lineage | null
  branchOf: Map<string, number>
  relationshipOf: (personId: string) => Relationship | null
}

/**
 * Turns a flat person list plus a focus id into everything the renderer needs.
 *
 * Split into three memos on purpose: the graph only rebuilds when the data
 * changes, while focus changes recompute the cheap derived pieces. In
 * `isolate` mode focus also changes what is rendered, so the layout comes back
 * into the dependency chain.
 */
export function useFamilyTree({
  people,
  focusId,
  focusMode = "highlight",
  layout: layoutOptions,
}: UseFamilyTreeOptions): FamilyTreeModel {
  const graph = React.useMemo(() => buildGraph(people), [people])

  const lineage = React.useMemo(
    () =>
      focusId && graph.personById.has(focusId)
        ? lineageOf(graph, focusId)
        : null,
    [graph, focusId]
  )

  // Isolate mode re-runs the whole pipeline over the filtered people, so the
  // layout tightens up around the line instead of leaving holes where the
  // hidden cards used to be.
  const visibleGraph = React.useMemo(() => {
    if (focusMode !== "isolate" || !lineage) return graph

    const keep = lineage.all
    const filtered = graph.people
      .filter((person) => keep.has(person.id))
      // Spreading, not mutating: `people` belongs to the caller and has to come
      // back out of this component exactly as it went in.
      // oxlint-disable-next-line oxc/no-map-spread
      .map((person) => ({
        ...person,
        parentIds: person.parentIds?.filter((id) => keep.has(id)),
        partnerIds: person.partnerIds?.filter((id) => keep.has(id)),
        partnerships: person.partnerships?.filter((p) => keep.has(p.partnerId)),
      }))

    return buildGraph(filtered)
  }, [graph, lineage, focusMode])

  const layout = React.useMemo(
    () => layoutTree(visibleGraph, layoutOptions),
    [visibleGraph, layoutOptions]
  )

  const branchOf = React.useMemo(
    () => assignBranches(visibleGraph, focusId).branchOf,
    [visibleGraph, focusId]
  )

  // The returned closure owns a cache keyed to this focus person, which is the
  // whole point — the compiler cannot prove that, but discarding the memo would
  // rebuild every ancestor walk on each render.
  // oxlint-disable-next-line react/preserve-manual-memoization
  const relationshipOf = React.useMemo(() => {
    if (!focusId || !visibleGraph.personById.has(focusId)) return () => null

    // One context per focus person, so the ancestor walks are computed once and
    // reused across every card rather than per render.
    const ctx = createKinshipContext()
    const cache = new Map<string, Relationship>()

    return (personId: string) => {
      const hit = cache.get(personId)
      if (hit) return hit
      const value = relationshipTo(visibleGraph, focusId, personId, ctx)
      cache.set(personId, value)
      return value
    }
  }, [visibleGraph, focusId])

  return { graph, visibleGraph, layout, lineage, branchOf, relationshipOf }
}

/** Reports graph problems once per dataset, in development only. */
export function useGraphDiagnostics(graph: FamilyGraph) {
  React.useEffect(() => {
    if (process.env.NODE_ENV === "production") return
    if (graph.diagnostics.length === 0) return

    console.groupCollapsed(
      `[family-tree] ${graph.diagnostics.length} data issue(s)`
    )
    for (const diagnostic of graph.diagnostics) {
      console.warn(`${diagnostic.code}: ${diagnostic.message}`)
    }
    console.groupEnd()
  }, [graph])
}

import * as React from "react"
import type { Rect } from "./types"

export interface Transform {
  x: number
  y: number
  scale: number
}

export interface ViewportOptions {
  minScale?: number
  maxScale?: number
  /** Padding kept around the content when fitting, in screen pixels. */
  fitPadding?: number
  /** Extra room reserved at the bottom, for a floating toolbar. */
  fitBottomInset?: number
}

const DEFAULTS = {
  minScale: 0.15,
  maxScale: 2.5,
  fitPadding: 48,
  fitBottomInset: 0,
}
const TWEEN_MS = 420

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value))

/** Ease-out cubic — decelerates into place without overshooting. */
const ease = (t: number) => 1 - Math.pow(1 - t, 3)

function prefersReducedMotion() {
  return (
    typeof window !== "undefined" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
  )
}

/**
 * Pan and zoom over a fixed-size content plane, with no dependencies.
 *
 * Drag pans, wheel zooms toward the cursor, two fingers pinch. Momentum is
 * deliberately left out: on a graph you are usually aiming at a specific card,
 * and glide makes that harder rather than nicer.
 */
export function useViewport(options: ViewportOptions = {}) {
  const opts = { ...DEFAULTS, ...options }
  const containerRef = React.useRef<HTMLDivElement | null>(null)
  const [transform, setTransform] = React.useState<Transform>({
    x: 0,
    y: 0,
    scale: 1,
  })

  // The container measures zero on the first paint, so anything that needs its
  // size (fitting the tree on load) has to wait for a real measurement.
  const [size, setSize] = React.useState({ width: 0, height: 0 })

  React.useEffect(() => {
    const container = containerRef.current
    if (!container) return

    const observer = new ResizeObserver(([entry]) => {
      const { width, height } = entry.contentRect
      setSize((current) =>
        current.width === width && current.height === height
          ? current
          : { width, height }
      )
    })

    observer.observe(container)
    return () => observer.disconnect()
  }, [])

  const frameRef = React.useRef<number | null>(null)
  // Mirrored into a ref so the imperative helpers below can read the current
  // transform without taking it as a dependency. Written in an effect rather
  // than during render — every read happens in an event handler or a callback,
  // all of which run after commit.
  const transformRef = React.useRef(transform)
  React.useEffect(() => {
    transformRef.current = transform
  }, [transform])

  const cancelTween = React.useCallback(() => {
    if (frameRef.current !== null) {
      cancelAnimationFrame(frameRef.current)
      frameRef.current = null
    }
  }, [])

  const tweenTo = React.useCallback(
    (target: Transform) => {
      cancelTween()

      if (prefersReducedMotion()) {
        setTransform(target)
        return
      }

      const from = transformRef.current
      const start = performance.now()

      const step = (now: number) => {
        const t = clamp((now - start) / TWEEN_MS, 0, 1)
        const k = ease(t)
        setTransform({
          x: from.x + (target.x - from.x) * k,
          y: from.y + (target.y - from.y) * k,
          scale: from.scale + (target.scale - from.scale) * k,
        })
        frameRef.current = t < 1 ? requestAnimationFrame(step) : null
      }

      frameRef.current = requestAnimationFrame(step)
    },
    [cancelTween]
  )

  React.useEffect(() => cancelTween, [cancelTween])

  /** Frames `rect` (in content coordinates) inside the container. */
  const fitTo = React.useCallback(
    (rect: Rect, maxScale = 1) => {
      const container = containerRef.current
      if (!container || rect.width <= 0 || rect.height <= 0) return

      const { width, height } = container.getBoundingClientRect()
      const pad = opts.fitPadding * 2
      // The usable band stops short of the toolbar, and its centre sits that
      // much higher than the container's — otherwise the bottom row of cards
      // ends up underneath the controls.
      const usableHeight = height - opts.fitBottomInset
      const scale = clamp(
        Math.min(
          (width - pad) / rect.width,
          (usableHeight - pad) / rect.height
        ),
        opts.minScale,
        Math.min(opts.maxScale, maxScale)
      )

      tweenTo({
        scale,
        x: width / 2 - (rect.x + rect.width / 2) * scale,
        y: usableHeight / 2 - (rect.y + rect.height / 2) * scale,
      })
    },
    [
      opts.fitPadding,
      opts.fitBottomInset,
      opts.minScale,
      opts.maxScale,
      tweenTo,
    ]
  )

  /** Brings a point in content coordinates to the middle of the container. */
  const centerOn = React.useCallback(
    (point: { x: number; y: number }, scale?: number) => {
      const container = containerRef.current
      if (!container) return

      const { width, height } = container.getBoundingClientRect()
      const nextScale = clamp(
        scale ?? transformRef.current.scale,
        opts.minScale,
        opts.maxScale
      )

      tweenTo({
        scale: nextScale,
        x: width / 2 - point.x * nextScale,
        y: height / 2 - point.y * nextScale,
      })
    },
    [opts.minScale, opts.maxScale, tweenTo]
  )

  /** Zooms about the container's centre, for the toolbar buttons. */
  const zoomBy = React.useCallback(
    (factor: number) => {
      const container = containerRef.current
      if (!container) return

      const { width, height } = container.getBoundingClientRect()
      const current = transformRef.current
      const next = clamp(current.scale * factor, opts.minScale, opts.maxScale)
      if (next === current.scale) return

      const ratio = next / current.scale
      tweenTo({
        scale: next,
        x: width / 2 - (width / 2 - current.x) * ratio,
        y: height / 2 - (height / 2 - current.y) * ratio,
      })
    },
    [opts.minScale, opts.maxScale, tweenTo]
  )

  /* ------------------------------ interaction ------------------------------ */

  const pointers = React.useRef(new Map<number, { x: number; y: number }>())
  const gesture = React.useRef<{
    // Pan origin, in screen pixels.
    startX: number
    startY: number
    originX: number
    originY: number
    // Pinch baseline.
    distance: number
    scale: number
  } | null>(null)

  const [isPanning, setIsPanning] = React.useState(false)

  const onPointerDown = React.useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      // Let clicks on cards through; only empty canvas starts a pan.
      if ((event.target as HTMLElement).closest("[data-ft-interactive]")) return

      cancelTween()
      const element = event.currentTarget
      element.setPointerCapture(event.pointerId)
      pointers.current.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY,
      })

      const current = transformRef.current
      if (pointers.current.size === 1) {
        gesture.current = {
          startX: event.clientX,
          startY: event.clientY,
          originX: current.x,
          originY: current.y,
          distance: 0,
          scale: current.scale,
        }
        setIsPanning(true)
      } else if (pointers.current.size === 2) {
        const [a, b] = [...pointers.current.values()]
        gesture.current = {
          startX: (a.x + b.x) / 2,
          startY: (a.y + b.y) / 2,
          originX: current.x,
          originY: current.y,
          distance: Math.hypot(a.x - b.x, a.y - b.y),
          scale: current.scale,
        }
      }
    },
    [cancelTween]
  )

  const onPointerMove = React.useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      if (!pointers.current.has(event.pointerId) || !gesture.current) return
      pointers.current.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY,
      })

      const g = gesture.current

      if (pointers.current.size >= 2) {
        const [a, b] = [...pointers.current.values()]
        const distance = Math.hypot(a.x - b.x, a.y - b.y)
        if (g.distance === 0) return

        const scale = clamp(
          (g.scale * distance) / g.distance,
          opts.minScale,
          opts.maxScale
        )
        const midX = (a.x + b.x) / 2
        const midY = (a.y + b.y) / 2
        const ratio = scale / g.scale

        setTransform({
          scale,
          x: midX - (g.startX - g.originX) * ratio - (midX - g.startX),
          y: midY - (g.startY - g.originY) * ratio - (midY - g.startY),
        })
        return
      }

      setTransform((current) => ({
        ...current,
        x: g.originX + (event.clientX - g.startX),
        y: g.originY + (event.clientY - g.startY),
      }))
    },
    [opts.minScale, opts.maxScale]
  )

  const onPointerUp = React.useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      pointers.current.delete(event.pointerId)
      if (pointers.current.size === 0) {
        gesture.current = null
        setIsPanning(false)
      }
    },
    []
  )

  /**
   * Wheel zooms about the cursor. Registered manually rather than via a React
   * prop because React attaches wheel listeners passively, and this one must
   * call `preventDefault` to stop the page scrolling behind the tree.
   */
  React.useEffect(() => {
    const container = containerRef.current
    if (!container) return

    const onWheel = (event: WheelEvent) => {
      event.preventDefault()
      cancelTween()

      const rect = container.getBoundingClientRect()
      const pointerX = event.clientX - rect.left
      const pointerY = event.clientY - rect.top

      setTransform((current) => {
        // Trackpads report small deltas continuously; the exponent keeps the
        // response even across mice and trackpads alike.
        const factor = Math.exp(-event.deltaY * 0.0015)
        const scale = clamp(
          current.scale * factor,
          opts.minScale,
          opts.maxScale
        )
        if (scale === current.scale) return current

        const ratio = scale / current.scale
        return {
          scale,
          x: pointerX - (pointerX - current.x) * ratio,
          y: pointerY - (pointerY - current.y) * ratio,
        }
      })
    }

    container.addEventListener("wheel", onWheel, { passive: false })
    return () => container.removeEventListener("wheel", onWheel)
  }, [cancelTween, opts.minScale, opts.maxScale])

  return {
    containerRef,
    transform,
    isPanning,
    size,
    setTransform,
    fitTo,
    centerOn,
    zoomBy,
    handlers: {
      onPointerDown,
      onPointerMove,
      onPointerUp,
      onPointerCancel: onPointerUp,
    },
  }
}
